"""Changelog and version files from Conventional Commit messages. See task.md."""

from __future__ import annotations

import pathlib
import re


class CommitError(ValueError):
    """Raised when `previous_version` is not a valid `X.Y.Z` version."""


def build(commits: list[str], previous_version: str, out_dir: str) -> None:
    """Write `<out_dir>/CHANGELOG.md` and `<out_dir>/version.txt`."""
    # Validate previous_version first (before creating any directories)
    validate_version(previous_version)

    # Parse commits
    parsed_commits = []
    for commit in commits:
        parsed = parse_commit(commit)
        if parsed is not None:
            parsed_commits.append(parsed)

    # Determine version bump
    new_version = determine_version(previous_version, parsed_commits)

    # Generate CHANGELOG.md content
    changelog_content = generate_changelog(new_version, parsed_commits)

    # Create output directory and write files
    out_path = pathlib.Path(out_dir)
    out_path.mkdir(parents=True, exist_ok=True)

    (out_path / "CHANGELOG.md").write_text(changelog_content, encoding="utf-8")
    (out_path / "version.txt").write_text(new_version + "\n", encoding="utf-8")


def validate_version(version: str) -> None:
    """Raise CommitError if version is not X.Y.Z format."""
    parts = version.split(".")
    if len(parts) != 3:
        raise CommitError(f"Invalid version: {version}")

    for part in parts:
        if not part:
            raise CommitError(f"Invalid version: {version}")
        if not part.isdigit():
            raise CommitError(f"Invalid version: {version}")
        if len(part) > 1 and part[0] == '0':
            raise CommitError(f"Invalid version: {version}")


def parse_commit(commit: str) -> dict | None:
    """Parse a commit message and return commit data or None if invalid."""
    # Split at first \n\n
    parts = commit.split("\n\n", 1)
    subject = parts[0].strip()
    body = parts[1].strip() if len(parts) > 1 else ""

    # Parse subject as conventional commit
    parsed = parse_subject(subject)
    if parsed is None:
        return None

    # Check for breaking change in body
    is_breaking = parsed["breaking"] or has_breaking_change_in_body(body)

    return {
        "type": parsed["type"],
        "scope": parsed["scope"],
        "description": parsed["description"],
        "breaking": is_breaking,
    }


def parse_subject(subject: str) -> dict | None:
    """Parse a Conventional Commit subject line."""
    pattern = r'^([a-z]+)(?:\(([^()]*)\))?(!)?:\s*(.*)$'
    match = re.match(pattern, subject)

    if not match:
        return None

    type_part = match.group(1)
    scope = match.group(2)
    has_bang = match.group(3) is not None
    description = match.group(4).strip()

    # Description must not be empty
    if not description:
        return None

    # Scope should be stripped of whitespace
    if scope:
        scope = scope.strip()
        if not scope:
            scope = None

    return {
        "type": type_part,
        "scope": scope,
        "description": description,
        "breaking": has_bang,
    }


def has_breaking_change_in_body(body: str) -> bool:
    """Check if body contains BREAKING CHANGE: or BREAKING-CHANGE:."""
    for line in body.split("\n"):
        stripped = line.strip()
        if stripped.startswith("BREAKING CHANGE:") or stripped.startswith("BREAKING-CHANGE:"):
            return True
    return False


def determine_version(previous_version: str, parsed_commits: list[dict]) -> str:
    """Determine the new version based on commits."""
    parts = previous_version.split(".")
    major, minor, patch = int(parts[0]), int(parts[1]), int(parts[2])

    has_breaking = any(c["breaking"] for c in parsed_commits)
    has_feat = any(c["type"] == "feat" for c in parsed_commits)
    has_fix_or_perf = any(c["type"] in ("fix", "perf") for c in parsed_commits)

    if has_breaking:
        return f"{major + 1}.0.0"
    elif has_feat:
        return f"{major}.{minor + 1}.0"
    elif has_fix_or_perf:
        return f"{major}.{minor}.{patch + 1}"
    else:
        return previous_version


def generate_changelog(new_version: str, parsed_commits: list[dict]) -> str:
    """Generate CHANGELOG.md content."""
    lines = [f"## {new_version}"]

    # Group commits by section
    breaking_changes = []
    features = []
    fixes = []
    performance = []

    for commit in parsed_commits:
        if commit["breaking"]:
            breaking_changes.append(commit)
        elif commit["type"] == "feat":
            features.append(commit)
        elif commit["type"] == "fix":
            fixes.append(commit)
        elif commit["type"] == "perf":
            performance.append(commit)

    # Deduplicate and sort
    breaking_changes = deduplicate_and_sort_commits(breaking_changes)
    features = deduplicate_and_sort_commits(features)
    fixes = deduplicate_and_sort_commits(fixes)
    performance = deduplicate_and_sort_commits(performance)

    # Format and add sections
    sections = [
        ("### Breaking changes", breaking_changes),
        ("### Features", features),
        ("### Fixes", fixes),
        ("### Performance", performance),
    ]

    for heading, commits in sections:
        if commits:
            lines.append("")
            lines.append(heading)
            lines.append("")
            for commit in commits:
                lines.append(format_entry(commit))

    return "\n".join(lines) + "\n"


def deduplicate_and_sort_commits(commits: list[dict]) -> list[dict]:
    """Deduplicate and sort commits."""
    # Use a dict to deduplicate by (scope, description)
    seen = {}
    for commit in commits:
        key = (commit["scope"], commit["description"])
        if key not in seen:
            seen[key] = commit

    # Sort by scope (entries without scope come last) and then by description
    def sort_key(commit):
        scope = commit["scope"] or ""
        desc = commit["description"]
        if commit["scope"]:
            return (0, scope, desc)
        else:
            return (1, "", desc)

    return sorted(seen.values(), key=sort_key)


def format_entry(commit: dict) -> str:
    """Format a commit as a changelog entry."""
    if commit["scope"]:
        return f"- **{commit['scope']}**: {commit['description']}"
    else:
        return f"- {commit['description']}"
